static const lv_image_dsc_t glow_blue = {
    .header = { .magic = LV_IMAGE_HEADER_MAGIC, .cf = LV_COLOR_FORMAT_RGB565,
                .w = 320, .h = 320, .stride = 320 * 2 },
    .data_size = sizeof(glow_blue_map), .data = glow_blue_map,
};

