const lv_image_dsc_t* frij_glow_for(uint32_t accent)
{
    switch (accent) {
        case 0x38BDF8: return &glow_blue;
        case 0xA855F7: return &glow_purple;
        case 0xFACC15: return &glow_amber;
        case 0xF472B6: return &glow_pink;
        case 0x22C55E: return &glow_green;
        case 0x7C3AED: return &glow_violet;
        default: return &glow_blue;  // unknown accent -> blue default
    }
}
